from scipy.optimize import least_squares as LS
def R(p):
    pw,qw,w=p
    M=np.column_stack([np.ones_like(t),x**pw,v**qw,np.cos(w*t),np.sin(w*t),t,x*v])
    c,_,_,_=np.linalg.lstsq(M,dv_dt,rcond=None)
    return dv_dt-M@c
best=None
for pw in [0.5,1,2,3]:
  for qw in [0.5,1,2,3]:
    for w in [0.3,1,2,3]:
        try:
            r=LS(R,[pw,qw,w],bounds=([-3,-3,0.01],[5,5,8]))
            e=np.std(r.fun)/np.std(dv_dt)
            if best is None or e<best[0]: best=(e,r.x)
        except Exception: pass
